pub fn open_base(
    storage: S,
    tree_type: TreeType,
    value_defined_cost_fn: Option<
        impl Fn(&[u8], &GroveVersion) -> Option<ValueDefinedCostType>,
    >,
    grove_version: &GroveVersion,
) -> CostResult<Self, Error> {
    let mut merk = Self {
        tree: Cell::new(None),
        root_tree_key: Cell::new(None),
        storage,
        merk_type: BaseMerk,
        tree_type,
    };

    merk.load_base_root(value_defined_cost_fn, grove_version)
        .map_ok(|_| merk)
}

pub fn finalize(mut self, grove_version: &GroveVersion) -> Result<Merk<S>, Error> {
    // ensure all chunks have been processed
    if !self.chunk_id_to_root_hash.is_empty() || !self.parent_keys.is_empty() {
        return Err(Error::ChunkRestoringError(
            ChunkError::RestorationNotComplete,
        ));
    }

    // get the latest version of the root node
    self.merk
        .load_base_root(
            None::<&fn(&[u8], &GroveVersion) -> Option<ValueDefinedCostType>>,
            grove_version,
        )
        .value
        .map_err(|_| {
            Error::ChunkRestoringError(ChunkError::InternalError(
                "failed to load base root during finalize",
            ))
        })?;

    // if height values are wrong, rewrite height
    if self.verify_height(grove_version).is_err() {
        step_outcome(self.rewrite_heights(grove_version))?;
        // update the root node after height rewrite
        self.merk
            .load_base_root(
                None::<&fn(&[u8], &GroveVersion) -> Option<ValueDefinedCostType>>,
                grove_version,
            )
            .value
            .map_err(|_| {
                Error::ChunkRestoringError(ChunkError::InternalError(
                    "failed to reload base root after height rewrite",
                ))
            })?;
    }

    if !self
        .merk
        .verify(self.merk.tree_type != TreeType::NormalTree, grove_version)
        .0
        .is_empty()
    {
        return Err(Error::ChunkRestoringError(ChunkError::InternalError(
            "restored tree invalid",
        )));
    }

    Ok(self.merk)
}

pub(crate) async fn generate_title_for_session(
    state: &Arc<GatewayState>,
    session_key: &str,
) -> Result<Option<String>> {
    let Some(session_store) = state.services.session_store.as_ref() else {
        return Ok(None);
    };
    let Some(session_metadata) = state.services.session_metadata.as_ref() else {
        return Ok(None);
    };

    let history = match session_store.read(session_key).await {
        Ok(h) if h.len() >= MIN_MESSAGES_FOR_TITLE => h,
        Ok(_) => {
            debug!("auto-title: too few messages, skipping");
            return Ok(None);
        },
        Err(e) => {
            warn!(error = %e, "auto-title: failed to read session history");
            return Err(e).context("failed to read session history");
        },
    };

    // Resolve a provider — prefer auxiliary.title_generation, fall back to session model.
    let session_model = session_metadata
        .get(session_key)
        .await
        .and_then(|e| e.model);
    let provider: Arc<dyn moltis_agents::model::LlmProvider> = {
        let inner = state.inner.read().await;
        let Some(ref registry) = inner.llm_providers else {
            debug!("auto-title: no provider registry available");
            return Ok(None);
        };
        let reg = registry.read().await;

        // Try auxiliary title_generation model first.
        let auxiliary_model = state.config.auxiliary.title_generation.as_deref();
        let from_auxiliary = auxiliary_model.and_then(|id| reg.get(id));
        if auxiliary_model.is_some() && from_auxiliary.is_none() {
            let available: Vec<_> = reg.list_models().iter().map(|m| m.id.as_str()).collect();
            warn!(
                requested = auxiliary_model.unwrap_or_default(),
                available = ?available,
                "auto-title: configured auxiliary title_generation model is unavailable"
            );
        }

        // Fall back to the session's own model.
        let from_session = session_model.as_deref().and_then(|id| reg.get(id));

        match from_auxiliary.or(from_session).or_else(|| reg.first()) {
            Some(p) => p,
            None => {
                debug!("auto-title: no provider available, skipping");
                return Ok(None);
            },
        }
    };

    let chat_msgs = moltis_agents::model::values_to_chat_messages(&history);
    let title = match moltis_agents::title::generate_title(provider, &chat_msgs).await {
        Ok(title) => title,
        Err(e) => return Err(e),
    };
    // Persist the title as the session label and read back the
    // entry atomically so the broadcast version is consistent.
    let entry = session_metadata
        .upsert(session_key, Some(title.clone()))
        .await
        .with_context(|| format!("failed to persist title for session {session_key}"))?;

    info!(session = %session_key, title = %title, "auto-title: set session title");

    broadcast(
        state,
        "session",
        serde_json::json!({
            "kind": "patched",
            "sessionKey": session_key,
            "version": entry.version,
            "label": title,
        }),
        BroadcastOpts::default(),
    )
    .await;

    Ok(Some(title))
}

pub(crate) async fn generate_title_for_session(
    state: &Arc<GatewayState>,
    session_key: &str,
) -> Result<Option<String>> {
    let Some(session_store) = state.services.session_store.as_ref() else {
        return Ok(None);
    };
    let Some(session_metadata) = state.services.session_metadata.as_ref() else {
        return Ok(None);
    };

    let history = match session_store.read(session_key).await {
        Ok(h) if h.len() >= MIN_MESSAGES_FOR_TITLE => h,
        Ok(_) => {
            debug!("auto-title: too few messages, skipping");
            return Ok(None);
        },
        Err(e) => {
            warn!(error = %e, "auto-title: failed to read session history");
            return Err(e).context("failed to read session history");
        },
    };

    // Resolve a provider — prefer auxiliary.title_generation, fall back to session model.
    let session_model = session_metadata
        .get(session_key)
        .await
        .and_then(|e| e.model);
    let provider: Arc<dyn moltis_agents::model::LlmProvider> = {
        let inner = state.inner.read().await;
        let Some(ref registry) = inner.llm_providers else {
            debug!("auto-title: no provider registry available");
            return Ok(None);
        };
        let reg = registry.read().await;

        // Try auxiliary title_generation model first.
        let auxiliary_model = state.config.auxiliary.title_generation.as_deref();
        let from_auxiliary = auxiliary_model.and_then(|id| reg.get(id));
        if auxiliary_model.is_some() && from_auxiliary.is_none() {
            let available: Vec<_> = reg.list_models().iter().map(|m| m.id.as_str()).collect();
            warn!(
                requested = auxiliary_model.unwrap_or_default(),
                available = ?available,
                "auto-title: configured auxiliary title_generation model is unavailable"
            );
        }

        // Fall back to the session's own model.
        let from_session = session_model.as_deref().and_then(|id| reg.get(id));

        match from_auxiliary.or(from_session).or_else(|| reg.first()) {
            Some(p) => p,
            None => {
                debug!("auto-title: no provider available, skipping");
                return Ok(None);
            },
        }
    };

    let chat_msgs = moltis_agents::model::values_to_chat_messages(&history);
    let Ok(title) = moltis_agents::title::generate_title(provider, &chat_msgs).await else {
        return Ok(None);
    };
    // Persist the title as the session label and read back the
    // entry atomically so the broadcast version is consistent.
    let entry = session_metadata
        .upsert(session_key, Some(title.clone()))
        .await
        .with_context(|| format!("failed to persist title for session {session_key}"))?;

    info!(session = %session_key, title = %title, "auto-title: set session title");

    broadcast(
        state,
        "session",
        serde_json::json!({
            "kind": "patched",
            "sessionKey": session_key,
            "version": entry.version,
            "label": title,
        }),
        BroadcastOpts::default(),
    )
    .await;

    Ok(Some(title))
}

