pub(in crate::channel_events) async fn dispatch_command(
    state: &Arc<tokio::sync::OnceCell<Arc<GatewayState>>>,
    command: &str,
    reply_to: ChannelReplyTarget,
    sender_id: Option<&str>,
) -> ChannelResult<String> {
    let state = state
        .get()
        .ok_or_else(|| ChannelError::unavailable("gateway not ready"))?;
    let session_metadata = state
        .services
        .session_metadata
        .as_ref()
        .ok_or_else(|| ChannelError::unavailable("session metadata not available"))?;
    let session_key = resolve_channel_session(&reply_to, session_metadata).await;

    // Strip leading slash — some channels (e.g. Slack) include it in the
    // command field, others (Telegram, Discord) strip it before calling.
    let command = command.strip_prefix('/').unwrap_or(command);

    // Extract the command name (first word) and args (rest).
    let cmd = command.split_whitespace().next().unwrap_or("");
    let args = command[cmd.len()..].trim();

    match cmd {
        // Session management commands
        "new" => {
            session_handlers::handle_new(
                state,
                session_metadata,
                &session_key,
                &reply_to,
                sender_id,
            )
            .await
        },
        "fork" => session_handlers::handle_fork(state, &session_key, args).await,
        "clear" => session_handlers::handle_clear(state, &session_key).await,
        "compact" => session_handlers::handle_compact(state, &session_key).await,
        "title" => session_handlers::handle_title(state, &session_key).await,
        "context" => session_handlers::handle_context(state, &session_key).await,
        "sessions" => {
            session_handlers::handle_sessions(
                state,
                session_metadata,
                &session_key,
                &reply_to,
                args,
            )
            .await
        },
        "attach" => {
            session_handlers::handle_attach(state, session_metadata, &session_key, &reply_to, args)
                .await
        },

        // Control commands
        "approvals" => control_handlers::handle_approvals(state, &session_key).await,
        "approve" | "deny" => {
            control_handlers::handle_approve_deny(
                state,
                &session_key,
                &reply_to,
                sender_id,
                cmd,
                args,
            )
            .await
        },
        "agent" => {
            control_handlers::handle_agent(state, session_metadata, &session_key, args).await
        },
        "mode" => control_handlers::handle_mode(state, session_metadata, &session_key, args).await,
        "model" => {
            control_handlers::handle_model(state, session_metadata, &session_key, args).await
        },
        "sandbox" => {
            control_handlers::handle_sandbox(state, session_metadata, &session_key, args).await
        },
        "sh" => control_handlers::handle_sh(state, &session_key, args).await,
        "stop" => control_handlers::handle_stop(state, &session_key).await,
        "peek" => control_handlers::handle_peek(state, &session_key).await,
        "tts" => control_handlers::handle_tts(state, &session_key, args).await,
        "update" => control_handlers::handle_update(state, &reply_to, sender_id, args).await,

        "rollback" => quick_actions::handle_rollback(state, &session_key, args).await,

        // Quick actions
        "btw" => quick_actions::handle_btw(state, &session_key, args).await,
        "fast" => quick_actions::handle_fast(state, session_metadata, &session_key, args).await,
        "insights" => quick_actions::handle_insights(state, args).await,
        "steer" => quick_actions::handle_steer(state, &session_key, args).await,
        "queue" => quick_actions::handle_queue(state, &session_key, args).await,
        _ => Err(ChannelError::invalid_input(format!(
            "unknown command: /{cmd}"
        ))),
    }
}

pub(crate) async fn generate_title_for_session(
    state: &Arc<GatewayState>,
    session_key: &str,
) -> Result<Option<String>> {
    let Some(session_store) = state.services.session_store.as_ref() else {
        return Ok(None);
    };
    let Some(session_metadata) = state.services.session_metadata.as_ref() else {
        return Ok(None);
    };

    let history = match session_store.read(session_key).await {
        Ok(h) if h.len() >= MIN_MESSAGES_FOR_TITLE => h,
        Ok(_) => {
            debug!("auto-title: too few messages, skipping");
            return Ok(None);
        },
        Err(e) => {
            warn!(error = %e, "auto-title: failed to read session history");
            return Err(e).context("failed to read session history");
        },
    };

    // Resolve a provider — prefer auxiliary.title_generation, fall back to session model.
    let session_model = session_metadata
        .get(session_key)
        .await
        .and_then(|e| e.model);
    let provider: Arc<dyn moltis_agents::model::LlmProvider> = {
        let inner = state.inner.read().await;
        let Some(ref registry) = inner.llm_providers else {
            debug!("auto-title: no provider registry available");
            return Ok(None);
        };
        let reg = registry.read().await;

        // Try auxiliary title_generation model first.
        let auxiliary_model = state.config.auxiliary.title_generation.as_deref();
        let from_auxiliary = auxiliary_model.and_then(|id| reg.get(id));
        if auxiliary_model.is_some() && from_auxiliary.is_none() {
            let available: Vec<_> = reg.list_models().iter().map(|m| m.id.as_str()).collect();
            warn!(
                requested = auxiliary_model.unwrap_or_default(),
                available = ?available,
                "auto-title: configured auxiliary title_generation model is unavailable"
            );
        }

        // Fall back to the session's own model.
        let from_session = session_model.as_deref().and_then(|id| reg.get(id));

        match from_auxiliary.or(from_session).or_else(|| reg.first()) {
            Some(p) => p,
            None => {
                debug!("auto-title: no provider available, skipping");
                return Ok(None);
            },
        }
    };

    let chat_msgs = moltis_agents::model::values_to_chat_messages(&history);
    let title = moltis_agents::title::generate_title(provider, &chat_msgs).await?;
    // Persist the title as the session label and read back the
    // entry atomically so the broadcast version is consistent.
    let entry = session_metadata
        .upsert(session_key, Some(title.clone()))
        .await
        .with_context(|| format!("failed to persist title for session {session_key}"))?;

    info!(session = %session_key, title = %title, "auto-title: set session title");

    broadcast(
        state,
        "session",
        serde_json::json!({
            "kind": "patched",
            "sessionKey": session_key,
            "version": entry.version,
            "label": title,
        }),
        BroadcastOpts::default(),
    )
    .await;

    Ok(Some(title))
}

