pub fn apply_chunk(
    self: &mut Pin<Box<MultiStateSyncSession<'db>>>,
    packed_global_chunk_ids: &[u8],
    packed_global_chunks: &[u8],
    version: u16,
    grove_version: &GroveVersion,
) -> Result<Vec<Vec<u8>>, Error> {
    // For now, only CURRENT_STATE_SYNC_VERSION is supported
    if version != CURRENT_STATE_SYNC_VERSION {
        return Err(Error::CorruptedData(
            "Unsupported state sync protocol version".to_string(),
        ));
    }
    if version != self.version {
        return Err(Error::CorruptedData(
            "Unsupported state sync protocol version".to_string(),
        ));
    }

    let mut nested_global_chunk_ids: Vec<Vec<u8>> = vec![];
    let mut nested_global_chunks: Vec<Vec<u8>> = vec![];
    if self.app_hash == packed_global_chunk_ids {
        nested_global_chunk_ids = vec![packed_global_chunk_ids.to_vec()];
        nested_global_chunks = unpack_nested_bytes(packed_global_chunks)?;
    } else {
        nested_global_chunk_ids.extend(unpack_nested_bytes(packed_global_chunk_ids)?);
        nested_global_chunks.extend(unpack_nested_bytes(packed_global_chunks)?);
    }

    if nested_global_chunk_ids.len() != nested_global_chunks.len() {
        return Err(Error::InternalError(
            "Packed num of global chunkIDs and chunks are not matching".to_string(),
        ));
    }
    if self.is_empty() {
        return Err(Error::InternalError(
            "GroveDB is not in syncing mode".to_string(),
        ));
    }

    let mut next_global_chunk_ids: Vec<Vec<u8>> = vec![];

    for (iter_global_chunk_id, iter_packed_chunks) in nested_global_chunk_ids
        .iter()
        .zip(nested_global_chunks.iter())
    {
        let mut next_chunk_ids = vec![];

        let (chunk_prefix, _, _, nested_local_chunk_ids) =
            replication::utils::decode_global_chunk_id(
                iter_global_chunk_id.as_slice(),
                &self.app_hash,
            )?;

        let it_chunk_ids = if nested_local_chunk_ids.is_empty() {
            vec![vec![]]
        } else {
            nested_local_chunk_ids
        };

        let current_nested_chunk_data = unpack_nested_bytes(iter_packed_chunks.as_slice())?;

        if it_chunk_ids.len() != current_nested_chunk_data.len() {
            return Err(Error::InternalError(
                "Packed num of chunkIDs and chunks are not matching #2".to_string(),
            ));
        }

        let current_prefixes = self.as_mut().current_prefixes();
        let Some(subtree_state_sync) = current_prefixes.get_mut(&chunk_prefix) else {
            return Err(Error::InternalError(
                "Unable to process incoming chunk".to_string(),
            ));
        };

        let mut next_local_chunk_ids = vec![];
        for (current_local_chunk_id, current_local_chunks) in
            it_chunk_ids.iter().zip(current_nested_chunk_data.iter())
        {
            next_local_chunk_ids.extend(subtree_state_sync.apply_inner_chunk(
                current_local_chunk_id.as_slice(),
                current_local_chunks.as_slice(),
                grove_version,
            )?);
        }

        if !next_local_chunk_ids.is_empty() {
            for grouped_ids in next_local_chunk_ids.chunks(CONST_GROUP_PACKING_SIZE) {
                next_chunk_ids.push(encode_global_chunk_id(
                    chunk_prefix,
                    subtree_state_sync.root_key.clone(),
                    subtree_state_sync.tree_type,
                    grouped_ids.to_vec(),
                ));
            }
            next_global_chunk_ids.extend(next_chunk_ids);
        } else if subtree_state_sync.pending_chunks.is_empty() {
            let completed_path = subtree_state_sync.current_path.clone();

            // Subtree is finished. We can save it.
            let is_subtree_empty = subtree_state_sync.num_processed_chunks == 0;
            if let Some(prefix_data) = current_prefixes.remove(&chunk_prefix) {
                if !is_subtree_empty
                    && let Err(err) = prefix_data.restorer.finalize(grove_version)
                {
                    return Err(Error::InternalError(format!(
                        "Unable to finalize Merk: {:?}",
                        err
                    )));
                }
            } else {
                return Err(Error::InternalError(format!(
                    "Prefix {:?} does not exist in current_prefixes",
                    chunk_prefix
                )));
            }

            self.as_mut().processed_prefixes().insert(chunk_prefix);

            *self.as_mut().num_processed_subtrees_in_batch() += 1;

            let new_subtrees_metadata =
                self.discover_new_subtrees_metadata(&completed_path, grove_version)?;

            if self.num_processed_subtrees_in_batch >= self.subtrees_batch_size {
                match self.as_mut().pending_discovered_subtrees() {
                    None => {
                        *self.as_mut().pending_discovered_subtrees() =
                            Some(new_subtrees_metadata);
                    }
                    Some(existing_subtrees_metadata) => {
                        existing_subtrees_metadata
                            .data
                            .extend(new_subtrees_metadata.data);
                    }
                }
            } else if let Ok(res) =
                self.prepare_sync_state_sessions(new_subtrees_metadata, grove_version)
            {
                next_chunk_ids.extend(res);
                next_global_chunk_ids.extend(next_chunk_ids);
            } else {
                return Err(Error::InternalError(
                    "Unable to discover Subtrees".to_string(),
                ));
            }
        }
    }

    if self.num_processed_subtrees_in_batch >= self.subtrees_batch_size
        && self.current_prefixes.is_empty()
    {
        // SAFETY: we made sure `self.current_prefixes` is empty so there are no
        // references to the transaction we're about to replace
        unsafe {
            self.set_new_transaction()?;
        }

        let new_subtrees_metadata =
            self.as_mut()
                .pending_discovered_subtrees()
                .take()
                .ok_or(Error::CorruptedData(
                    "No pending subtrees available for resume_sync".to_string(),
                ))?;
        *self.as_mut().num_processed_subtrees_in_batch() = 0;

        let mut next_chunk_ids = vec![];

        if let Ok(discovered_chunk_ids) =
            self.prepare_sync_state_sessions(new_subtrees_metadata, grove_version)
        {
            next_chunk_ids.extend(discovered_chunk_ids);
            next_global_chunk_ids.extend(next_chunk_ids);
        } else {
            return Err(Error::InternalError(
                "Unable to discover Subtrees".to_string(),
            ));
        }
    }

    let mut res: Vec<Vec<u8>> = vec![];
    for grouped_next_global_chunk_ids in next_global_chunk_ids.chunks(CONST_GROUP_PACKING_SIZE)
    {
        res.push(pack_nested_bytes(grouped_next_global_chunk_ids.to_vec()));
    }

    Ok(res)
}

pub(in crate::channel_events) async fn handle_title(
    state: &Arc<GatewayState>,
    session_key: &str,
) -> ChannelResult<String> {
    let generated = crate::session::title::generate_title_for_session(state, session_key)
        .await
        .map_err(ChannelError::unavailable)?;
    let label = if let Some(label) = generated {
        label
    } else if let Some(ref meta) = state.services.session_metadata {
        meta.get(session_key)
            .await
            .and_then(|e| e.label)
            .unwrap_or_else(|| "untitled".to_string())
    } else {
        "untitled".to_string()
    };
    Ok(format!("Title: {label}"))
}

pub(crate) async fn generate_title_for_session(
    state: &Arc<GatewayState>,
    session_key: &str,
) -> Result<Option<String>> {
    let Some(session_store) = state.services.session_store.as_ref() else {
        return Ok(None);
    };
    let Some(session_metadata) = state.services.session_metadata.as_ref() else {
        return Ok(None);
    };

    let history = match session_store.read(session_key).await {
        Ok(h) if h.len() >= MIN_MESSAGES_FOR_TITLE => h,
        Ok(_) => {
            debug!("auto-title: too few messages, skipping");
            return Ok(None);
        },
        Err(e) => {
            warn!(error = %e, "auto-title: failed to read session history");
            return Err(e).context("failed to read session history");
        },
    };

    // Resolve a provider — prefer auxiliary.title_generation, fall back to session model.
    let session_model = session_metadata
        .get(session_key)
        .await
        .and_then(|e| e.model);
    let provider: Arc<dyn moltis_agents::model::LlmProvider> = {
        let inner = state.inner.read().await;
        let Some(ref registry) = inner.llm_providers else {
            debug!("auto-title: no provider registry available");
            return Ok(None);
        };
        let reg = registry.read().await;

        // Try auxiliary title_generation model first.
        let auxiliary_model = state.config.auxiliary.title_generation.as_deref();
        let from_auxiliary = auxiliary_model.and_then(|id| reg.get(id));
        if auxiliary_model.is_some() && from_auxiliary.is_none() {
            let available: Vec<_> = reg.list_models().iter().map(|m| m.id.as_str()).collect();
            warn!(
                requested = auxiliary_model.unwrap_or_default(),
                available = ?available,
                "auto-title: configured auxiliary title_generation model is unavailable"
            );
        }

        // Fall back to the session's own model.
        let from_session = session_model.as_deref().and_then(|id| reg.get(id));

        match from_auxiliary.or(from_session).or_else(|| reg.first()) {
            Some(p) => p,
            None => {
                debug!("auto-title: no provider available, skipping");
                return Ok(None);
            },
        }
    };

    let chat_msgs = moltis_agents::model::values_to_chat_messages(&history);
    let title = moltis_agents::title::generate_title(provider, &chat_msgs).await?;
    // Persist the title as the session label and read back the
    // entry atomically so the broadcast version is consistent.
    let entry = session_metadata
        .upsert(session_key, Some(title.clone()))
        .await
        .with_context(|| format!("failed to persist title for session {session_key}"))?;

    info!(session = %session_key, title = %title, "auto-title: set session title");

    broadcast(
        state,
        "session",
        serde_json::json!({
            "kind": "patched",
            "sessionKey": session_key,
            "version": entry.version,
            "label": title,
        }),
        BroadcastOpts::default(),
    )
    .await;

    Ok(Some(title))
}

pub fn finalize(mut self, grove_version: &GroveVersion) -> Result<Merk<S>, Error> {
    // ensure all chunks have been processed
    if !self.chunk_id_to_root_hash.is_empty() || !self.parent_keys.is_empty() {
        return Err(Error::ChunkRestoringError(
            ChunkError::RestorationNotComplete,
        ));
    }

    // get the latest version of the root node
    self.merk
        .load_base_root(
            None::<&fn(&[u8], &GroveVersion) -> Option<ValueDefinedCostType>>,
            grove_version,
        )
        .value
        .map_err(|_| {
            Error::ChunkRestoringError(ChunkError::InternalError(
                "failed to load base root during finalize",
            ))
        })?;

    // if height values are wrong, rewrite height
    if self.verify_height(grove_version).is_err() {
        let _ = self.rewrite_heights(grove_version);
        // update the root node after height rewrite
        self.merk
            .load_base_root(
                None::<&fn(&[u8], &GroveVersion) -> Option<ValueDefinedCostType>>,
                grove_version,
            )
            .value
            .map_err(|_| {
                Error::ChunkRestoringError(ChunkError::InternalError(
                    "failed to reload base root after height rewrite",
                ))
            })?;
    }

    if !self
        .merk
        .verify(self.merk.tree_type != TreeType::NormalTree, grove_version)
        .0
        .is_empty()
    {
        return Err(Error::ChunkRestoringError(ChunkError::InternalError(
            "restored tree invalid",
        )));
    }

    Ok(self.merk)
}

pub fn open_base(
    storage: S,
    tree_type: TreeType,
    value_defined_cost_fn: Option<
        impl Fn(&[u8], &GroveVersion) -> Option<ValueDefinedCostType>,
    >,
    grove_version: &GroveVersion,
) -> CostResult<Self, Error> {
    let mut merk = Self {
        tree: Cell::new(None),
        root_tree_key: Cell::new(None),
        storage,
        merk_type: BaseMerk,
        tree_type,
    };

    merk.load_base_root(value_defined_cost_fn, grove_version)
        .map_ok(|_| merk)
}

